{"implementation": "def solve(case):
    segments = case["segments"]
    budget = case["budget"]

    min_sum = sum(s["minimum"] for s in segments)
    cap_sum = sum(s["capacity"] for s in segments)

    if budget < min_sum or budget > cap_sum:
        raise ValueError("Budget {} is outside valid range [{}, {}]".format(budget, min_sum, cap_sum))

    allocs = [s["minimum"] for s in segments]
    remaining = budget - min_sum

    while remaining > 0:
        best_idx = -1
        best_priority = -1.0
        for i, s in enumerate(segments):
            if allocs[i] < s["capacity"]:
                priority = s["importance"] / (allocs[i] + 1)
                if priority > best_priority:
                    best_priority = priority
                    best_idx = i
        if best_idx == -1:
            break
        allocs[best_idx] += 1
        remaining -= 1

    by_name = {s["name"]: allocs[i] for i, s in enumerate(segments)}
    total = sum(allocs)

    return {
        "allocations": allocs,
        "by_name": by_name,
        "total": total
    }
"}
